use std::future::Future;

use agent_client_protocol::{ConnectionTo, Dispatch, Error, Handled, Role, RoleId, UntypedRole};

#[derive(Clone, Debug, PartialEq, Eq, PartialOrd, Ord, Hash)]
struct NonDefaultRole(u8);

impl Role for NonDefaultRole {
    type Counterpart = Self;

    fn role_id(&self) -> RoleId {
        RoleId::from_singleton(self)
    }

    fn default_handle_dispatch_from(
        &self,
        message: Dispatch,
        _connection: ConnectionTo<Self>,
    ) -> impl Future<Output = Result<Handled<Dispatch>, Error>> + Send {
        std::future::ready(Ok(Handled::No {
            message,
            retry: false,
        }))
    }

    fn counterpart(&self) -> Self::Counterpart {
        self.clone()
    }
}

#[test]
fn singleton_role_id_does_not_require_default() {
    let first = NonDefaultRole(1);
    let second = NonDefaultRole(2);

    assert_eq!(first.role_id(), RoleId::from_singleton(&first));
    assert_eq!(first.role_id(), second.role_id());
    assert_ne!(first.role_id(), UntypedRole.role_id());
}

#![cfg(feature = "server")]

use agent_client_protocol_http::{CorsOptions, ServerOptions};

#[test]
fn defaults_are_unchanged() {
    let options = ServerOptions::default();

    assert_eq!(options.path, "/acp");
    assert_eq!(options.cors, CorsOptions::disabled());
    assert!(options.health_endpoint);
}

#[test]
fn fluent_setters_replace_values_and_accept_owned_paths() {
    let cors = CorsOptions::allow_origins(["https://example.com"]).unwrap();
    let options = ServerOptions::default()
        .with_path("/initial")
        .with_path(String::from("/agent"))
        .with_cors(CorsOptions::allow_any_origin())
        .with_cors(cors.clone())
        .with_health_endpoint(true)
        .with_health_endpoint(false);

    assert_eq!(options.path, "/agent");
    assert_eq!(options.cors, cors);
    assert!(!options.health_endpoint);
}

#[test]
fn each_setter_preserves_other_defaults() {
    let path = ServerOptions::default().with_path("/agent");
    assert_eq!(path.cors, CorsOptions::disabled());
    assert!(path.health_endpoint);

    let cors = ServerOptions::default().with_cors(CorsOptions::allow_any_origin());
    assert_eq!(cors.path, "/acp");
    assert!(cors.health_endpoint);

    let health = ServerOptions::default().with_health_endpoint(false);
    assert_eq!(health.path, "/acp");
    assert_eq!(health.cors, CorsOptions::disabled());
}

#[test]
fn public_fields_remain_mutable() {
    let mut options = ServerOptions::default();
    options.path = "/agent".into();
    options.cors = CorsOptions::allow_any_origin();
    options.health_endpoint = false;

    assert_eq!(options.path, "/agent");
    assert_eq!(options.cors, CorsOptions::allow_any_origin());
    assert!(!options.health_endpoint);
}

//! Arrow proxy example that can be run as a standalone process.
//!
//! This adds '>' prefix to session updates for testing conductor proxy chains.

use agent_client_protocol_test::arrow_proxy::run_arrow_proxy;
use tokio_util::compat::{TokioAsyncReadCompatExt, TokioAsyncWriteCompatExt};

#[tokio::main]
async fn main() -> Result<(), Box<dyn std::error::Error>> {
    // Initialize tracing for debugging
    tracing_subscriber::fmt()
        .with_target(true)
        .with_writer(std::io::stderr)
        .init();

    tracing::info!("Arrow proxy starting");

    // Create connection over stdio with compat layer for tokio/futures interop
    let stdin = tokio::io::stdin().compat();
    let stdout = tokio::io::stdout().compat_write();

    // Run the arrow proxy
    run_arrow_proxy(agent_client_protocol::ByteStreams::new(stdout, stdin)).await?;

    Ok(())
}
